/**
 * ============================================================================
 * 視覺藝術作品署名與靈感宣告 (ATTRIBUTION & INSPIRATION DECLARATION)
 * ============================================================================
 * 作者 (Author / Code Adaptor): Uncler M
 * 靈感啟發來源 (Inspired By): 郭銳文 (Raven Kwok) - "生成艺术作品 - 算法“花窗”分形"
 * 原始作品討論 (Original Note): http://xhslink.com/o/54BBlfFDQF
 * 授權協議 (License): Creative Commons Attribution-NonCommercial-ShareAlike 4.0 (CC BY-NC-SA 4.0)
 * 
 * [說明 / Notice]
 * 本作品由 Uncler M 編寫與視聽化對應。演算法靈感取材自郭銳文先生創作之「遞迴化
 * Voronoi 結構與哥德式玫瑰花窗彩繪玻璃分形」視覺概念。
 * 專為 4K MV Visual Integration Editor 專案打造。
 * ============================================================================
 */

let SYMMETRY_SECTORS = 8;
let primarySites = [];
let rotationAngle = 0;

let smoothedSubBass = 0.0;
let smoothedPercussive = 0.0;
let smoothedMid = 0.0;

setup = () => {
  p5.disableFriendlyErrors = true;
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1.0);
  ellipseMode(CENTER);

  // 初始化同心同徑主 Voronoi 節點陣列
  let rings = [100, 220, 360, 500];
  let counts = [6, 12, 18, 24];

  for (let r = 0; r < rings.length; r++) {
    let radius = rings[r];
    let count = counts[r];
    for (let i = 0; i < count; i++) {
      let a = (TWO_PI / count) * i;
      primarySites.push({
        r: radius,
        baseAngle: a,
        ringIdx: r,
        subSites: generateSubSites(radius, a)
      });
    }
  }
};

function generateSubSites(baseR, baseA) {
  let list = [];
  let numSub = int(random(3, 7));
  for (let s = 0; s < numSub; s++) {
    list.push({
      dr: random(-35, 35),
      da: random(-0.15, 0.15),
      hueOffset: random(-40, 40)
    });
  }
  return list;
}

draw = () => {
  // 1. 動態音訊信號平滑處理
  let rawSubBass = (typeof sub_bass !== 'undefined') ? sub_bass : (typeof sub_bass_ratio !== 'undefined' ? sub_bass_ratio : (mouseIsPressed ? 0.85 : 0.22));
  let rawPercussive = (typeof percussive !== 'undefined') ? percussive : (mouseIsPressed ? 0.9 : 0.1);
  let rawMid = (typeof mid !== 'undefined') ? mid : (typeof mid_ratio !== 'undefined' ? mid_ratio : 0.3);

  smoothedSubBass += (rawSubBass - smoothedSubBass) * 0.14;
  smoothedPercussive += (rawPercussive - smoothedPercussive) * 0.28;
  smoothedMid += (rawMid - smoothedMid) * 0.18;

  rotationAngle += 0.003 + smoothedMid * 0.012;

  // 2. 聖殿暗黑莊嚴背景
  background(260, 40, 5, 0.3);

  let cx = width * 0.5;
  let cy = height * 0.5;
  let currentHue = (typeof chord_hue !== 'undefined' && chord_hue > 0) ? chord_hue : 280;

  // 3. 計算徑向對稱下的 Voronoi 頂點與花窗幾何
  let activePoints = [];

  for (let i = 0; i < primarySites.length; i++) {
    let ps = primarySites[i];
    let dynR = ps.r * (1.0 + smoothedSubBass * 0.25);
    let dynA = ps.baseAngle + rotationAngle * (ps.ringIdx % 2 === 0 ? 1 : -1);

    // 繪製遞迴一級主節點
    let px = cx + dynR * cos(dynA);
    let py = cy + dynR * sin(dynA);

    activePoints.push({ x: px, y: py, ring: ps.ringIdx, hue: (currentHue + ps.ringIdx * 35) % 360 });

    // 遞迴二級子 Voronoi 分形節點 (Recursive Sub-Sites)
    if (smoothedSubBass > 0.35) {
      for (let s = 0; s < ps.subSites.length; s++) {
        let sub = ps.subSites[s];
        let subX = cx + (dynR + sub.dr) * cos(dynA + sub.da);
        let subY = cy + (dynR + sub.dr) * sin(dynA + sub.da);
        activePoints.push({ x: subX, y: subY, ring: ps.ringIdx + 1, hue: (currentHue + sub.hueOffset) % 360 });
      }
    }
  }

  // 4. 繪製哥德式彩繪玻璃花窗圖騰 (Stained Glass Gothic Polygons)
  strokeWeight(2.0 + smoothedSubBass * 3.5);

  for (let i = 0; i < activePoints.length; i++) {
    let p1 = activePoints[i];

    for (let j = i + 1; j < activePoints.length; j++) {
      let p2 = activePoints[j];
      let d = dist(p1.x, p1.y, p2.x, p2.y);

      if (d < 110 + smoothedSubBass * 50) {
        let glassAlpha = map(d, 0, 160, 0.85, 0.1);
        let glassHue = (p1.hue + p2.hue) * 0.5;

        // 哥德式彩繪玻璃填充與金屬鉛條勾勒 (Gothic Lead Lines)
        stroke(0, 0, 15, glassAlpha * 0.9); // 哥德式花窗黑鉛線條
        fill(glassHue, 85, 95 + smoothedPercussive * 45, glassAlpha * (0.35 + smoothedPercussive * 0.45));

        // 繪製對稱多邊形花窗單元
        triangle(p1.x, p1.y, p2.x, p2.y, cx, cy);
      }
    }
  }

  // 5. 重拍觸發「哥德式彩繪玻璃光透脈衝 (Stained Glass Light Pulse)」
  if (smoothedPercussive > 0.55) {
    noFill();
    stroke((currentHue + 40) % 360, 30, 100, smoothedPercussive * 0.8);
    strokeWeight(4.0 + smoothedPercussive * 8.0);
    ellipse(cx, cy, 400 * (1.0 + smoothedPercussive * 0.5), 400 * (1.0 + smoothedPercussive * 0.5));
  }

  // 6. 花窗核心圓環與神聖幾何框架
  noFill();
  stroke(0, 0, 100, 0.6);
  strokeWeight(2.5);
  ellipse(cx, cy, 180, 180);
  ellipse(cx, cy, 440, 440);
  ellipse(cx, cy, 720, 720);
};

